insert into public.policies (id, workspace_id, name, slug, description, draft, created_by, created_at, updated_at) values
  ('00000007-0000-4000-8000-000000000001', '00000002-0000-4000-8000-000000000001', 'Core Standards', 'core-standards', 'Baseline commands, coding standards and security rules for every repository.', '{"overview":{"summary":"Engineering standards every Northwind Labs and client repository follows. Agents should read this before making changes.","stack":["TypeScript","Node.js","GitHub Actions"]},"commands":{"install":"{{packageManager}} install","test":"{{packageManager}} test","lint":"{{packageManager}} run lint","typecheck":"{{packageManager}} run typecheck","build":"{{packageManager}} run build"},"codingStandards":[{"rule":"Keep functions small and named for what they return.","severity":"should"},{"rule":"Never commit secrets, tokens or .env files.","severity":"must"},{"rule":"Add or update tests for every behavior change.","severity":"must"},{"rule":"Prefer explicit return types on exported functions.","severity":"should"},{"rule":"Log with the shared logger, never console.log in committed code.","severity":"must"}],"security":{"secrets":"Read secrets from environment variables only. Never log them.","forbiddenPaths":[".env*","**/*.pem","infra/secrets/**"],"dependencies":"Ask before adding a new runtime dependency."},"pullRequests":{"branchNaming":"type/short-description, e.g. fix/login-redirect","commitStyle":"conventional","checklist":["Tests pass locally","No unrelated changes","Screenshots for UI changes"]},"overrides":{"claude":{"append":"Use plan mode for changes that touch more than three files.","mode":"full"},"copilot":{"append":"Suggest tests alongside implementation changes."}}}'::jsonb, '00000001-0000-4000-8000-000000000002', '2026-08-12T11:00:00.000Z', '2026-11-15T18:40:00.000Z'),
  ('00000007-0000-4000-8000-000000000002', '00000002-0000-4000-8000-000000000001', 'Next.js + Supabase', 'nextjs-supabase', 'App Router, server actions and RLS conventions for product web apps.', null, '00000001-0000-4000-8000-000000000003', '2026-09-10T11:00:00.000Z', '2026-11-12T16:00:00.000Z'),
  ('00000007-0000-4000-8000-000000000003', '00000002-0000-4000-8000-000000000001', 'Python Service', 'python-service', 'uv, pytest and ruff conventions for services and data pipelines.', null, '00000001-0000-4000-8000-000000000003', '2026-10-08T11:00:00.000Z', '2026-10-13T16:00:00.000Z');
insert into public.policy_versions (id, workspace_id, policy_id, semver, content, changelog, content_hash, published_by, published_at, created_at, updated_at) values
  ('00000008-0000-4000-8000-000000000001', '00000002-0000-4000-8000-000000000001', '00000007-0000-4000-8000-000000000001', '2.1.0', '{"overview":{"summary":"Engineering standards every Northwind Labs and client repository follows. Agents should read this before making changes.","stack":["TypeScript","Node.js","GitHub Actions"]},"commands":{"install":"{{packageManager}} install","test":"{{packageManager}} test","lint":"{{packageManager}} run lint","typecheck":"{{packageManager}} run typecheck","build":"{{packageManager}} run build"},"codingStandards":[{"rule":"Keep functions small and named for what they return.","severity":"should"},{"rule":"Never commit secrets, tokens or .env files.","severity":"must"},{"rule":"Add or update tests for every behavior change.","severity":"must"}],"security":{"secrets":"Read secrets from environment variables only. Never log them.","forbiddenPaths":[".env*","**/*.pem"],"dependencies":"Ask before adding a new runtime dependency."},"pullRequests":{"branchNaming":"type/short-description, e.g. fix/login-redirect","commitStyle":"conventional","checklist":["Tests pass locally","No unrelated changes"]},"overrides":{}}'::jsonb, 'Import from the v1 workspace. Adds pull request conventions.', 'sha256:7b2e57b4334e114f1bf18a5e75515614cc8105eb710debf81754002347b3a549', '00000001-0000-4000-8000-000000000002', '2026-08-19T16:00:00.000Z', '2026-08-19T16:00:00.000Z', '2026-08-19T16:00:00.000Z'),
  ('00000008-0000-4000-8000-000000000002', '00000002-0000-4000-8000-000000000001', '00000007-0000-4000-8000-000000000001', '2.2.0', '{"overview":{"summary":"Engineering standards every Northwind Labs and client repository follows. Agents should read this before making changes.","stack":["TypeScript","Node.js","GitHub Actions"]},"commands":{"install":"{{packageManager}} install","test":"{{packageManager}} test","lint":"{{packageManager}} run lint","typecheck":"{{packageManager}} run typecheck","build":"{{packageManager}} run build"},"codingStandards":[{"rule":"Keep functions small and named for what they return.","severity":"should"},{"rule":"Never commit secrets, tokens or .env files.","severity":"must"},{"rule":"Add or update tests for every behavior change.","severity":"must"},{"rule":"Prefer explicit return types on exported functions.","severity":"should"}],"security":{"secrets":"Read secrets from environment variables only. Never log them.","forbiddenPaths":[".env*","**/*.pem"],"dependencies":"Ask before adding a new runtime dependency."},"pullRequests":{"branchNaming":"type/short-description, e.g. fix/login-redirect","commitStyle":"conventional","checklist":["Tests pass locally","No unrelated changes","Screenshots for UI changes"]},"overrides":{}}'::jsonb, 'Prefer explicit return types; screenshots required for UI changes.', 'sha256:a7085c56fc3417853f0541411c2412d8538d659cd00dd082a9d561b5a5f3f146', '00000001-0000-4000-8000-000000000002', '2026-09-29T16:00:00.000Z', '2026-09-29T16:00:00.000Z', '2026-09-29T16:00:00.000Z'),
  ('00000008-0000-4000-8000-000000000003', '00000002-0000-4000-8000-000000000001', '00000007-0000-4000-8000-000000000001', '2.3.0', '{"overview":{"summary":"Engineering standards every Northwind Labs and client repository follows. Agents should read this before making changes.","stack":["TypeScript","Node.js","GitHub Actions"]},"commands":{"install":"{{packageManager}} install","test":"{{packageManager}} test","lint":"{{packageManager}} run lint","typecheck":"{{packageManager}} run typecheck","build":"{{packageManager}} run build"},"codingStandards":[{"rule":"Keep functions small and named for what they return.","severity":"should"},{"rule":"Never commit secrets, tokens or .env files.","severity":"must"},{"rule":"Add or update tests for every behavior change.","severity":"must"},{"rule":"Prefer explicit return types on exported functions.","severity":"should"}],"security":{"secrets":"Read secrets from environment variables only. Never log them.","forbiddenPaths":[".env*","**/*.pem","infra/secrets/**"],"dependencies":"Ask before adding a new runtime dependency."},"pullRequests":{"branchNaming":"type/short-description, e.g. fix/login-redirect","commitStyle":"conventional","checklist":["Tests pass locally","No unrelated changes","Screenshots for UI changes"]},"overrides":{"claude":{"append":"Use plan mode for changes that touch more than three files.","mode":"full"},"copilot":{"append":"Suggest tests alongside implementation changes."}}}'::jsonb, 'Forbid infra/secrets/**. Adds Claude plan-mode and Copilot test-suggestion overrides.', 'sha256:0e9c86dbb5c671a0536c82b5ab8d445dae9dea1f6ff5a3087f632402b44aa711', '00000001-0000-4000-8000-000000000001', '2026-10-28T16:00:00.000Z', '2026-10-28T16:00:00.000Z', '2026-10-28T16:00:00.000Z'),
  ('00000008-0000-4000-8000-000000000004', '00000002-0000-4000-8000-000000000001', '00000007-0000-4000-8000-000000000002', '1.0.0', '{"overview":{"summary":"Conventions for Next.js App Router projects backed by Supabase.","stack":["Next.js","React","Supabase","Tailwind CSS"]},"commands":{"install":"{{packageManager}} install","dev":"{{packageManager}} dev","test":"{{packageManager}} test","lint":"{{packageManager}} lint","typecheck":"{{packageManager}} typecheck","build":"{{packageManager}} build"},"codingStandards":[{"rule":"Default to Server Components; add ''use client'' only when needed.","severity":"must"},{"rule":"Validate every server action input with Zod.","severity":"must"},{"rule":"Query Supabase with the user''s session so RLS applies.","severity":"must"}],"security":{"secrets":"Only NEXT_PUBLIC_ variables may reach the browser.","forbiddenPaths":[".env*","supabase/.temp/**"]},"pullRequests":{"commitStyle":"conventional","checklist":["Migrations included","Types regenerated"]},"overrides":{"claude":{"append":"Run the typecheck before declaring a task done.","mode":"full"}}}'::jsonb, 'First version, from the Next.js + Supabase template.', 'sha256:0c3ea206d4676f8d9eb0331a63bfb52ee7a297a35397e13b71f50b1bcb81ed9c', '00000001-0000-4000-8000-000000000003', '2026-09-14T16:00:00.000Z', '2026-09-14T16:00:00.000Z', '2026-09-14T16:00:00.000Z'),
  ('00000008-0000-4000-8000-000000000005', '00000002-0000-4000-8000-000000000001', '00000007-0000-4000-8000-000000000002', '1.1.0', '{"overview":{"summary":"Conventions for Next.js App Router projects backed by Supabase.","stack":["Next.js","React","Supabase","Tailwind CSS"]},"commands":{"install":"{{packageManager}} install","dev":"{{packageManager}} dev","test":"{{packageManager}} test","lint":"{{packageManager}} lint","typecheck":"{{packageManager}} typecheck","build":"{{packageManager}} build"},"codingStandards":[{"rule":"Default to Server Components; add ''use client'' only when needed.","severity":"must"},{"rule":"Validate every server action input with Zod.","severity":"must"},{"rule":"Query Supabase with the user''s session so RLS applies.","severity":"must"},{"rule":"Wrap uncached data reads in Suspense with a skeleton fallback.","severity":"should"}],"security":{"secrets":"Only NEXT_PUBLIC_ variables may reach the browser.","forbiddenPaths":[".env*","supabase/.temp/**"]},"pullRequests":{"commitStyle":"conventional","checklist":["Migrations included","Types regenerated"]},"overrides":{"claude":{"append":"Run the typecheck before declaring a task done.","mode":"full"}}}'::jsonb, 'Wrap uncached reads in Suspense with skeleton fallbacks.', 'sha256:533de670972032f48653240facefdfa57c9eb94ee9dd495e1831110d8c1e828a', '00000001-0000-4000-8000-000000000003', '2026-11-12T16:00:00.000Z', '2026-11-12T16:00:00.000Z', '2026-11-12T16:00:00.000Z'),
  ('00000008-0000-4000-8000-000000000006', '00000002-0000-4000-8000-000000000001', '00000007-0000-4000-8000-000000000003', '1.0.0', '{"overview":{"summary":"Standards for Python services and data pipelines.","stack":["Python 3.13","uv","pytest","ruff"]},"commands":{"install":"uv sync","test":"uv run pytest","lint":"uv run ruff check .","typecheck":"uv run mypy ."},"codingStandards":[{"rule":"Type-annotate all public functions.","severity":"must"},{"rule":"Use pathlib over os.path.","severity":"should"}],"security":{"forbiddenPaths":[".env*","data/raw/**"]},"pullRequests":{"commitStyle":"conventional","checklist":["pytest passes","ruff clean"]},"overrides":{}}'::jsonb, 'First version for Python services.', 'sha256:ed6a62325df449687a576a2060422d4648177d6f500c92e5b7c26d3671c7a36d', '00000001-0000-4000-8000-000000000003', '2026-10-13T16:00:00.000Z', '2026-10-13T16:00:00.000Z', '2026-10-13T16:00:00.000Z');
